select d.id,'code','coding','beginner',$q$Sum of digits$q$,$q$Sum of digits$q$,null,null,3,$q$Repeatedly take n % 10 and divide n by 10, adding each digit.$q$,$q${"description": "Read a non-negative integer and print the sum of its digits.", "input_format": "A single integer N.", "output_format": "Print the sum of the digits of N.", "constraints": "0 <= N <= 10^9", "examples": [{"input": "123", "output": "6"}, {"input": "9", "output": "9"}]}$q$::jsonb,array['java'],$q${"lang": "java", "starter": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        // write your code here\n    }\n}\n"}$q$::jsonb from domains d where d.slug='java' on conflict do nothing;
insert into coding_tests(question_id,input,expected,is_hidden,position)
select qq.id,v.i,v.o,v.h,v.p from questions qq join domains d on d.id=qq.domain_id cross join (values ($q$123$q$,$q$6$q$,false,1),($q$9$q$,$q$9$q$,false,2),($q$1000$q$,$q$1$q$,true,3),($q$98765$q$,$q$35$q$,true,4),($q$0$q$,$q$0$q$,true,5)) as v(i,o,h,p)
where d.slug='java' and qq.text=$q$Sum of digits$q$ and not exists (select 1 from coding_tests c where c.question_id=qq.id);
